import {esc,trackExperience} from './config.mjs';
export function reviewFields(form){const f=new FormData(form);return [['Empresa',f.get('companyName')],['Razão social',f.get('legalName')],['CNPJ',f.get('cnpj')],['Cidade e UF',[f.get('city'),f.get('stateCode')].join(' / ')],['Categoria',f.get('category')],['Link público',f.get('destinationUrl')],['Descrição',f.get('companyDescription')],['Oferta',f.get('communityOffer')||'Sem oferta'],['Condições',f.get('offerConditions')||'Não informadas'],['Validade da oferta',f.get('offerExpiresOn')||'Não informada'],['Responsável',f.get('contactName')],['E-mail',f.get('email')],['Logo',f.get('logo')?.name||''],['Capa',f.get('cover')?.name||'']]}
export function reviewMarkup(fields){return '<h3>Confira sua empresa antes de continuar</h3><p>Pagamento único, sete dias de presença após confirmação e aprovação. Confira o valor apresentado acima e os dados que serão enviados.</p><dl>'+fields.map(([label,value])=>'<dt>'+esc(label)+'</dt><dd>'+esc(value)+'</dd>').join('')+'</dl><div class="review-actions"><button type="button" class="btn" data-confirm-registration>Confirmar dados e continuar</button><button type="button" class="btn secondary" data-edit-registration>Voltar e editar</button></div>'}
if(typeof document!=='undefined'){
 let lastTrigger=null,lastPage='';const routeEvent=()=>{const key=location.pathname+'|'+location.hash.split('/')[0];if(key===lastPage)return;lastPage=key;const event=location.pathname==='/ir-alem/'?(location.hash.startsWith('#novo')?'company_registration':!location.hash||location.hash==='#patrocinadores'?'company_directory':null):location.hash==='#enviar'?'compose_video':location.hash.startsWith('#acompanhar')?'order_lookup':null;if(event)trackExperience(event)};routeEvent();window.addEventListener('hashchange',routeEvent);
 document.addEventListener('click',e=>{const target=e.target.closest?.('button,a');if(target&&!target.closest('dialog'))lastTrigger=target;if(target?.id==='cinema-participate')trackExperience('participation_open');if(target?.dataset.participation)trackExperience('compose_'+target.dataset.participation);if(target?.tagName==='A'&&/^https:\/\/(www\.)?(youtube\.com|tiktok\.com)\//.test(target.href))trackExperience('channel_open')},true);
 const enhanced=new WeakSet();
 const enhance=()=>{
  document.querySelectorAll('dialog').forEach(dialog=>{if(enhanced.has(dialog))return;enhanced.add(dialog);const trigger=lastTrigger||document.activeElement,title=dialog.querySelector('h2');if(title){title.id=title.id||'dialog-title';dialog.setAttribute('aria-labelledby',title.id)}dialog.addEventListener('close',()=>{if(trigger?.isConnected)trigger.focus?.()});
   const picker=dialog.querySelector('.avatar-picker');if(picker){const options=[...picker.querySelectorAll('[role=option]')];const sync=()=>options.forEach(b=>b.tabIndex=b.getAttribute('aria-selected')==='true'?0:-1);sync();picker.addEventListener('click',()=>queueMicrotask(sync));picker.addEventListener('keydown',e=>{const i=options.indexOf(e.target),moves={ArrowRight:1,ArrowLeft:-1,ArrowDown:5,ArrowUp:-5};if(i<0||!(e.key in moves)&&!['Home','End'].includes(e.key))return;e.preventDefault();const next=e.key==='Home'?0:e.key==='End'?options.length-1:(i+moves[e.key]+options.length)%options.length;options[next].click();options[next].focus();sync()})}
  });
  const form=document.querySelector('#sponsor-form');if(form&&!enhanced.has(form)){enhanced.add(form);form.removeAttribute('novalidate');
   const sections=[['#sponsor-description','Apresentação pública'],['#sponsor-logo','Imagens da empresa'],['#sponsor-offer','Oferta à comunidade']];for(const [selector,label] of sections){const field=form.querySelector(selector)?.closest('.field'),target=selector==='#sponsor-logo'?field?.parentElement:field;if(target){const heading=document.createElement('h3');heading.className='registration-section';heading.textContent=label;target.before(heading)}}
   form.addEventListener('input',()=>{delete form.dataset.reviewReady;form.querySelector('.registration-review')?.remove()});
  }
 };
 let queued=false;const schedule=()=>{if(queued)return;queued=true;queueMicrotask(()=>{queued=false;enhance()})};new MutationObserver(schedule).observe(document.body,{childList:true,subtree:true});enhance();
 document.addEventListener('submit',e=>{const form=e.target;if(form.id!=='sponsor-form')return;if(!form.checkValidity()){e.preventDefault();e.stopImmediatePropagation();form.reportValidity();return}if(form.dataset.reviewReady==='true')return;e.preventDefault();e.stopImmediatePropagation();let review=form.querySelector('.registration-review');if(!review){review=document.createElement('section');review.className='registration-review';review.setAttribute('aria-label','Revisão do cadastro');form.append(review)}trackExperience('company_review');review.innerHTML=reviewMarkup(reviewFields(form));review.querySelector('[data-confirm-registration]').onclick=()=>{form.dataset.reviewReady='true';form.requestSubmit(form.querySelector('#sponsor-submit'))};review.querySelector('[data-edit-registration]').onclick=()=>{review.remove();form.querySelector('input')?.focus()};review.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});review.querySelector('button').focus()},true);
 const banner=document.createElement('div');banner.className='connection-status';banner.setAttribute('role','status');banner.setAttribute('aria-live','polite');banner.hidden=true;document.querySelector('header')?.after(banner);
 const connection=()=>{banner.hidden=navigator.onLine!==false;banner.textContent='Você está sem conexão. Algumas informações podem estar desatualizadas. Reconecte para enviar pedidos ou conferir pagamentos.'};window.addEventListener('offline',connection);window.addEventListener('online',connection);connection();
}
